CREATE TABLE IF NOT EXISTS user_email_verifications (user_id VARCHAR(191) PRIMARY KEY, verified_at VARCHAR(32) NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS auth_email_codes (id VARCHAR(36) PRIMARY KEY, normalized_email VARCHAR(254) NOT NULL, purpose VARCHAR(16) NOT NULL, code_hash CHAR(64) NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, attempts INT NOT NULL DEFAULT 0, delivered INT NOT NULL DEFAULT 0, consumed INT NOT NULL DEFAULT 0, INDEX auth_email_codes_lookup(normalized_email,purpose,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
